import React from "react";

function Ic({n,cls,st}){ return <i className={"ti ti-"+n+(cls?(" "+cls):"")} style={st}/>; }
function Sand({s=17,c="#FBF9F5"}){ return <svg width={s} height={s} viewBox="0 0 24 24" fill="none" stroke={c} strokeWidth="1.7" strokeLinecap="round" strokeLinejoin="round"><path d="M3.5 9 C3.5 5.5 20.5 5.5 20.5 9 L3.5 9 Z"/><path d="M3.5 12 C6 10.2 18 10.2 20.5 12"/><path d="M4 15 L20 15 L20 15.8 C20 16.7 19 17 18 17 L6 17 C5 17 4 16.7 4 15.8 Z"/></svg>; }
function Btn({onClick,variant,children,className}){ const v=variant==="dark"?"bg-[#2B1E1A] text-[#FBF9F5]":variant==="ghost"?"bg-[#FBF9F5] text-[#2B1E1A] border border-[#2B1E1A]/20":variant==="ghostD"?"bg-transparent text-[#FBF9F5] border border-[#FBF9F5]/25":"bg-[#C87A51] text-[#FBF9F5]"; return <button onClick={onClick} className={"w-full rounded-2xl py-[15px] text-[14px] font-semibold flex items-center justify-center gap-2 "+v+" "+(className||"")}>{children}</button>; }
function makeQR(color){ var n=13,c=150/n,s='<svg width="150" height="150" viewBox="0 0 150 150">'; function f(x,y){return '<rect x="'+x+'" y="'+y+'" width="'+c*3+'" height="'+c*3+'" fill="none" stroke="'+color+'" stroke-width="'+c*0.9+'"/>';} var sd=color==="#C87A51"?7:3; for(var r=0;r<n;r++){for(var k=0;k<n;k++){ if((r<4&&k<4)||(r<4&&k>n-5)||(r>n-5&&k<4))continue; sd=(sd*1103515245+12345)&0x7fffffff; if((sd>>8)%2===0)s+='<rect x="'+k*c+'" y="'+r*c+'" width="'+c+'" height="'+c+'" fill="'+color+'"/>'; }} s+=f(0,0)+f((n-3)*c,0)+f(0,(n-3)*c)+'</svg>'; return s; }
var LOGOS={cat:"data:image/png;base64,",obr:"data:image/png;base64,"};
var DATA={cat:{name:"Catalina's Café",color:"#C87A51",stamps:8,sub:"Café de especialidad y bollería",prize:"una infusión + un producto de bollería, a elección",ic:"coffee"},obr:{name:"El Obrador",color:"#7A8B7B",stamps:4,sub:"Sandwichería de autor",prize:"un sándwich a elección",ic:"sand"}};
var NAV=[["home","home","Inicio"],["card","ticket","Mi Tarjeta"],["news","sparkles","Novedades"],["exp","cup","Experiencias"]];

/* ============================================================
   PERSISTENCIA · SUPABASE (preparado para conectar)
   1) npm i @supabase/supabase-js
   2) En Vercel, definí las variables de entorno:
        VITE_SUPABASE_URL  y  VITE_SUPABASE_ANON_KEY
   3) Descomentá el bloque de abajo y reemplazá el cuerpo de "db".
   Esquema SQL sugerido:
     clientes(id uuid pk, nombre text, qr_code text unique, creado timestamptz)
     tarjetas(id uuid pk, cliente_id uuid fk, local text, sellos int, actualizado timestamptz)
     canjes  (id uuid pk, cliente_id uuid fk, local text, premio text, mozo text, fecha timestamptz)
   ============================================================ */
