function App(){
  const [screen,setScreen]=React.useState("welcome");
  const [local,setLocal]=React.useState("cat");
  const [qrOpen,setQrOpen]=React.useState(false);
  const [pin,setPin]=React.useState("");
  const [cpin,setCpin]=React.useState("");
  const [stampN,setStampN]=React.useState(1);
  function go(s){ if(s!=="card") setQrOpen(false); setScreen(s); }
  function openCard(l){ setLocal(l); setQrOpen(false); setScreen("card"); }
  function pressPin(d){ setPin(p=>{ var nv=(p+d).slice(0,4); if(nv.length===4){ setTimeout(()=>{ setPin(""); setStampN(1); setScreen("cajaStamp"); },250);} return nv; }); }
  function pressCpin(d){ setCpin(p=>{ var nv=(p+d).slice(0,4); if(nv.length===4){ setTimeout(()=>{ setCpin(""); setStampN(1); setScreen("cajaScan"); },250);} return nv; }); }

  const avatar=(on)=> <div onClick={on} className={"w-[38px] h-[38px] rounded-full bg-[#2B1E1A] text-[#FBF9F5] flex items-center justify-center text-sm font-semibold "+(on?"cursor-pointer":"")}>F</div>;
  function Header({title,on}){ return <div className="px-5 pt-5 pb-1.5 flex items-center justify-between"><p className="text-xl font-semibold">{title}</p>{avatar(on)}</div>; }
  function Back({to,dark}){ return <Ic n="arrow-left" cls="cursor-pointer" st={{fontSize:22,color:dark?"#FBF9F5":"#2B1E1A"}}/>; }

  function Nav(){ return <div className="border-t border-[#2B1E1A]/10 bg-[#FBF9F5] flex justify-around pt-3 pb-4">{NAV.map(x=>{ const on=screen===x[0]; return <div key={x[0]} onClick={()=>go(x[0])} className={"text-center cursor-pointer "+(on?"text-[#2B1E1A]":"text-[#B4ADA6]")}><Ic n={x[1]} st={{fontSize:22}}/><p className={"text-[10px] "+(on?"font-semibold":"")}>{x[2]}</p></div>; })}</div>; }

  function StampGrid(){ const d=DATA[local]; return <div className="grid grid-cols-5 gap-2.5 my-4">{Array.from({length:10}).map((_,i)=>{ const isGift=i===9, filled=i<d.stamps; return <div key={i} className="aspect-square rounded-full flex items-center justify-center" style={{background:isGift?"rgba(251,249,245,0.28)":filled?"rgba(251,249,245,0.22)":"rgba(251,249,245,0.06)",border:isGift?"1.5px solid rgba(251,249,245,0.6)":filled?"none":"1.5px dashed rgba(251,249,245,0.45)"}}>{isGift?<Ic n="gift" st={{fontSize:16,color:"#FBF9F5"}}/>:filled?(d.ic==="coffee"?<Ic n="coffee" st={{fontSize:15,color:"#FBF9F5"}}/>:<Sand s={15}/>):<span style={{fontSize:11,color:"rgba(251,249,245,0.6)"}}>{i+1}</span>}</div>; })}</div>; }

  const inputD="w-full mb-3.5 rounded-xl px-3 py-3 text-sm bg-[#FBF9F5]/[0.06] border border-[#FBF9F5]/20 text-[#FBF9F5] outline-none placeholder:text-[#FBF9F5]/40";
  const stepDesc="mt-1.5 text-[11.5px] text-[#C8BEB6] leading-[1.55]";

  const SCREENS={
    welcome:()=> <div className="h-full flex flex-col bg-[#2B1E1A] text-[#FBF9F5]">
      <div className="flex-1 flex flex-col items-center justify-center px-7 text-center">
        <img src={LOGOS.cat} className="w-[168px]" alt="Catalina's"/>
        <div className="flex items-center gap-3 my-5"><span className="w-9 h-px bg-[#FBF9F5]/30"></span><span className="text-[#8F877F]">+</span><span className="w-9 h-px bg-[#FBF9F5]/30"></span></div>
        <img src={LOGOS.obr} className="w-[188px]" alt="El Obrador"/>
        <p className="mt-7 text-sm text-[#C8BEB6] leading-relaxed">Tu café, tus sándwiches<br/>y tus premios, en un solo lugar.</p>
      </div>
      <div className="px-6 pb-10 pt-5"><Btn onClick={()=>go("howto")}>Empezar</Btn><p className="mt-5 text-center text-[13px] text-[#8F877F]">¿Ya tenés cuenta? <span onClick={()=>go("login")} className="text-[#C87A51] font-semibold cursor-pointer">Ingresá</span></p></div>
      <div className="pb-4 text-center text-[11px] text-[#8F877F]">¿Sos del local? <span onClick={()=>{setCpin("");go("cajaLogin");}} className="text-[#C87A51] font-semibold cursor-pointer">Abrir modo mozo</span></div>
    </div>,

    howto:()=> <div className="h-full flex flex-col bg-[#2B1E1A] text-[#FBF9F5]">
      <div className="flex-1 overflow-y-auto px-[30px] pt-8">
        <p className="text-[10.5px] tracking-[2.5px] text-[#C87A51] font-semibold">CÓMO FUNCIONA</p>
        <h1 className="mt-2.5 text-[25px] font-semibold leading-tight" style={{fontFamily:"'Playfair Display',serif"}}>Tu ritual,<br/><span className="italic text-[#C87A51]">recompensado</span></h1>
        <p className="mt-2.5 text-xs text-[#C8BEB6] leading-[1.5]">Porque volver siempre tiene que valer la pena. Cada infusión y cada sándwich te acercan a uno gratis.</p>
        <div className="mt-6">
          {[["01","#C87A51","Cada visita, un sello","Mostrás tu código en la caja y sumás. Una infusión en Catalina's Café, un sándwich en El Obrador.",true],["02","#C87A51","El décimo va por la casa","Juntá 9 sellos y el próximo es nuestro regalo: tu infusión o tu sándwich, a elección.",true],["03","#9EAE9E","El Desafío Dual del mes","Completá las dos tarjetas en un mismo mes y desbloqueás una Gift Card para gastar donde quieras.",false]].map((s,i)=>(
            <div key={i} className="flex gap-4"><div className="flex flex-col items-center w-[30px] flex-none"><span style={{fontFamily:"'Playfair Display',serif",fontSize:22,color:s[1]}}>{s[0]}</span>{s[4]&&<div className="flex-1 w-[1.5px] mt-2" style={{background:"rgba(200,122,81,0.35)"}}></div>}</div><div className="flex-1 pb-4"><p className="text-sm font-semibold">{s[2]}</p><p className={stepDesc}>{s[3]}</p></div></div>
          ))}
        </div>
      </div>
      <div className="px-[30px] pt-4 pb-7"><Btn onClick={()=>go("register")}>Crear mi cuenta</Btn><div className="flex justify-center gap-1.5 mt-3.5"><span className="w-[7px] h-[7px] rounded-full bg-[#FBF9F5]/20"></span><span className="w-5 h-[7px] rounded-full bg-[#C87A51]"></span><span className="w-[7px] h-[7px] rounded-full bg-[#FBF9F5]/20"></span></div></div>
    </div>,

    register:()=> <div className="h-full flex flex-col bg-[#2B1E1A] text-[#FBF9F5]"><div className="flex-1 overflow-y-auto p-5">
      <p className="mt-6 mb-1.5 text-[22px] font-semibold">Creá tu cuenta</p><p className="mb-5 text-xs text-[#C8BEB6]">Es gratis y toma un minuto.</p>
      <label className="text-xs text-[#C8BEB6]">Nombre</label><input defaultValue="Fabián" className={inputD}/>
      <label className="text-xs text-[#C8BEB6]">Email</label><input placeholder="tu@email.com" className={inputD}/>
      <label className="text-xs text-[#C8BEB6]">Celular</label><input placeholder="+54 9 ..." className={inputD}/>
      <Btn onClick={()=>go("home")} className="mb-3.5">Crear cuenta</Btn>
      <div className="flex items-center gap-2.5 mb-3.5"><div className="flex-1 h-px bg-[#FBF9F5]/15"></div><span className="text-xs text-[#8F877F]">o</span><div className="flex-1 h-px bg-[#FBF9F5]/15"></div></div>
      <Btn variant="ghostD" onClick={async()=>{ if(await auth.signInWithGoogle()) go("home"); }}><Ic n="brand-google"/>Continuar con Google</Btn>
    </div></div>,

    login:()=> <div className="h-full flex flex-col bg-[#2B1E1A] text-[#FBF9F5]"><div className="flex-1 overflow-y-auto p-5">
      <span onClick={()=>go("welcome")}><Back dark/></span>
      <p className="mt-5 mb-1.5 text-[22px] font-semibold">Hola de nuevo</p><p className="mb-5 text-xs text-[#C8BEB6]">Ingresá para ver tus sellos y premios.</p>
      <label className="text-xs text-[#C8BEB6]">Email</label><input placeholder="tu@email.com" className={inputD}/>
      <label className="text-xs text-[#C8BEB6]">Contraseña</label><input type="password" defaultValue="123456" className={inputD+" mb-2"}/>
      <p onClick={()=>go("recover")} className="text-right text-[11px] text-[#C87A51] mb-5 cursor-pointer">¿Olvidaste tu contraseña?</p>
      <Btn onClick={()=>go("home")} className="mb-3.5">Ingresar</Btn>
      <Btn variant="ghostD" onClick={async()=>{ if(await auth.signInWithGoogle()) go("home"); }}><Ic n="brand-google"/>Continuar con Google</Btn>
    </div></div>,

    recover:()=> <div className="h-full flex flex-col bg-[#2B1E1A] text-[#FBF9F5]"><div className="flex-1 overflow-y-auto p-5">
      <span onClick={()=>go("login")}><Back dark/></span>
      <p className="mt-5 mb-1.5 text-[22px] font-semibold">Recuperar contraseña</p><p className="mb-5 text-xs text-[#C8BEB6] leading-[1.55]">Ingresá tu email y te enviamos un enlace para crear una nueva.</p>
      <label className="text-xs text-[#C8BEB6]">Email</label><input placeholder="tu@email.com" className={inputD+" mb-[18px]"}/>
      <Btn onClick={()=>go("recoverSent")}>Enviar enlace</Btn>
    </div></div>,

    recoverSent:()=> <div className="h-full flex flex-col bg-[#2B1E1A] text-[#FBF9F5]"><div className="flex-1 p-5 text-center">
      <div className="w-[72px] h-[72px] rounded-full mx-auto mt-11 flex items-center justify-center" style={{background:"rgba(122,139,123,0.25)"}}><Ic n="mail" st={{fontSize:32,color:"#9EAE9E"}}/></div>
      <p className="text-xl font-semibold mt-4">Revisá tu correo</p>
      <p className="text-[12.5px] text-[#C8BEB6] leading-[1.6] mt-2 max-w-[250px] mx-auto">Te enviamos un enlace para restablecer tu contraseña. Puede tardar unos minutos en llegar.</p>
      <div className="max-w-[250px] mx-auto mt-6"><Btn variant="dark" onClick={()=>go("login")}><Ic n="arrow-left"/> Volver a ingresar</Btn></div>
    </div></div>,

    home:()=> <div className="h-full flex flex-col"><div className="flex-1 overflow-y-auto">
      <Header title={<span><span className="block text-xs text-[#7A8B7B] font-normal">Buen día,</span>Fabián</span>} on={()=>go("profile")}/>
      <div className="px-5 pt-2"><div className="bg-[#2B1E1A] text-[#FBF9F5] rounded-[20px] p-[18px]">
        <div className="flex items-center justify-between mb-3.5"><p className="text-sm font-semibold"><Ic n="gift" st={{color:"#C87A51",marginRight:6}}/>Desafío Dual · Julio</p><span className="text-[11px] px-2.5 py-[3px] rounded-full" style={{background:"rgba(251,249,245,0.14)"}}>12/18</span></div>
        <div className="flex gap-3.5">
          <div className="flex-1"><p className="text-xs text-[#C8BEB6] mb-1.5">Catalina's</p><div className="h-[7px] rounded-full overflow-hidden" style={{background:"rgba(251,249,245,0.14)"}}><div className="h-full" style={{width:"89%",background:"#C87A51"}}></div></div><p className="text-[11px] text-[#C8BEB6] mt-1.5">8 de 9</p></div>
          <div className="flex-1"><p className="text-xs text-[#C8BEB6] mb-1.5">El Obrador</p><div className="h-[7px] rounded-full overflow-hidden" style={{background:"rgba(251,249,245,0.14)"}}><div className="h-full" style={{width:"44%",background:"#7A8B7B"}}></div></div><p className="text-[11px] text-[#C8BEB6] mt-1.5">4 de 9</p></div>
        </div>
        <p className="mt-3.5 text-[11px] text-[#C8BEB6] leading-[1.5]">Completá ambas tarjetas este mes y ganás tu <b className="text-[#FBF9F5] font-semibold">Gift Card Dual</b>.</p>
      </div></div>
      <div className="px-5 pt-4 pb-1.5"><p className="text-xs text-[#7A8B7B] font-semibold mb-2.5">Mis tarjetas</p>
        <div onClick={()=>openCard("cat")} className="bg-[#FBF9F5] border border-[#2B1E1A]/10 rounded-2xl p-4 flex items-center justify-between mb-2.5 cursor-pointer"><div className="flex items-center gap-3"><div className="w-[38px] h-[38px] rounded-xl flex items-center justify-center" style={{background:"rgba(200,122,81,0.14)",color:"#C87A51"}}><Ic n="coffee"/></div><div><p className="text-sm font-semibold">Catalina's Café</p><p className="text-xs text-[#7A8B7B]">Te falta 1 sello para tu premio</p></div></div><Ic n="chevron-right" st={{color:"#B4ADA6"}}/></div>
        <div onClick={()=>openCard("obr")} className="bg-[#FBF9F5] border border-[#2B1E1A]/10 rounded-2xl p-4 flex items-center justify-between cursor-pointer"><div className="flex items-center gap-3"><div className="w-[38px] h-[38px] rounded-xl flex items-center justify-center" style={{background:"rgba(122,139,123,0.16)"}}><Sand s={20} c="#7A8B7B"/></div><div><p className="text-sm font-semibold">El Obrador</p><p className="text-xs text-[#7A8B7B]">Te faltan 5 sellos para tu premio</p></div></div><Ic n="chevron-right" st={{color:"#B4ADA6"}}/></div>
      </div>
      <div className="px-5 pt-2 pb-1.5"><p className="text-xs text-[#7A8B7B] font-semibold mb-2.5">Tus premios</p><div className="flex gap-2.5">
        <div onClick={()=>go("prize")} className="flex-1 cursor-pointer rounded-2xl p-3 text-center" style={{background:"rgba(200,122,81,0.10)",border:"1px solid rgba(200,122,81,0.22)"}}><Ic n="coffee" st={{color:"#C87A51",fontSize:20}}/><p className="text-xs mt-1.5" style={{color:"#99633B"}}>Premio listo</p></div>
        <div onClick={()=>go("giftcard")} className="flex-1 cursor-pointer rounded-2xl p-3 text-center" style={{background:"rgba(122,139,123,0.12)",border:"1px solid rgba(122,139,123,0.28)"}}><Ic n="gift" st={{color:"#7A8B7B",fontSize:20}}/><p className="text-xs mt-1.5" style={{color:"#41503F"}}>Gift Card Dual</p></div>
      </div></div>
      <div className="px-5 pt-2 pb-2">
        <div onClick={()=>go("news")} className="cursor-pointer rounded-2xl overflow-hidden border border-[#2B1E1A]/10 mb-3"><div className="h-[92px] bg-[#7A8B7B] flex items-end p-3"><span className="text-[11px] bg-[#FBF9F5] text-[#2B1E1A] px-2.5 py-[3px] rounded-full font-semibold">Novedad</span></div><div className="px-3.5 py-3"><p className="text-sm font-semibold">Nuevo grano: Etiopía Guji</p><p className="text-xs text-[#7A8B7B] mt-0.5">Notas florales y cítricas · desde hoy en barra</p></div></div>
        <div onClick={()=>go("exp")} className="cursor-pointer flex items-center justify-between rounded-2xl p-4" style={{background:"rgba(200,122,81,0.10)",border:"1px solid rgba(200,122,81,0.22)"}}><div className="flex items-center gap-3"><div className="w-[38px] h-[38px] rounded-xl bg-[#C87A51] text-[#FBF9F5] flex items-center justify-center"><Ic n="cup"/></div><div><p className="text-sm font-semibold">Taller de Masa Madre</p><p className="text-xs mt-0.5" style={{color:"#99633B"}}>Acceso prioritario · vie 15 ago</p></div></div><Ic n="chevron-right" st={{color:"#C87A51"}}/></div>
      </div>
    </div><Nav/></div>,

    card:()=>{ const d=DATA[local]; const falta=9-d.stamps; const msg=falta===0?"¡Tarjeta completa! Tu premio: "+d.prize+".":falta===1?"Te falta 1 sello para tu premio: "+d.prize+".":"Te faltan "+falta+" sellos para tu premio: "+d.prize+".";
      return <div className="h-full flex flex-col"><div className="flex-1 overflow-y-auto">
        <Header title="Mi Tarjeta"/>
        <div className="px-5 pt-1.5"><div className="rounded-2xl p-1 flex" style={{background:"rgba(43,30,26,0.06)"}}>{["cat","obr"].map(l=><div key={l} onClick={()=>openCard(l)} className={"flex-1 text-center py-2.5 rounded-xl text-[13px] font-semibold cursor-pointer "+(local===l?"bg-[#FBF9F5] text-[#2B1E1A] shadow":"text-[#7A8B7B]")}>{l==="cat"?"Catalina's":"El Obrador"}</div>)}</div></div>
        <div className="px-5 pt-4"><div className="rounded-[20px] p-5 text-[#FBF9F5]" style={{background:d.color}}>
          <div className="flex items-center justify-between"><div className="flex items-center gap-2.5"><div className="w-[34px] h-[34px] rounded-[10px] flex items-center justify-center" style={{background:"rgba(251,249,245,0.18)"}}>{d.ic==="coffee"?<Ic n="coffee" st={{fontSize:17}}/>:<Sand s={17}/>}</div><div><p className="text-[15px] font-semibold">{d.name}</p><p className="text-[11px] opacity-80">{d.sub}</p></div></div><div className="text-right"><p className="text-xl font-semibold">{d.stamps} / 9</p><p className="text-[10px] opacity-80">sellos</p></div></div>
          <StampGrid/>
          <p className="text-xs opacity-90 leading-[1.5]">{msg}</p>
        </div></div>
        <div className="px-5 py-4"><div className="bg-[#FBF9F5] border border-[#2B1E1A]/10 rounded-[18px] p-[18px] text-center">
          <p className="text-[13px] font-semibold text-[#2B1E1A]">Tu código de cliente</p>
          <p className="text-[11px] text-[#7A8B7B] mt-0.5 mb-3">Mostralo en caja o en la mesa para sumar tus sellos</p>
          <div className="w-[160px] h-[160px] mx-auto" dangerouslySetInnerHTML={{__html:makeQR("#2B1E1A")}}/>
          <div className="mt-3 inline-flex items-center gap-2.5 px-4 py-2 rounded-xl" style={{background:"rgba(43,30,26,0.05)"}}><Ic n="user" st={{fontSize:14,color:"#7A8B7B"}}/><span className="text-[13px] font-semibold tracking-[2px]">SOCIO-01042</span></div>
        </div></div>
      </div><Nav/></div>; },
    news:()=> <div className="h-full flex flex-col"><div className="flex-1 overflow-y-auto"><Header title="Novedades"/>
      <div className="px-5 pt-2">
        <div className="rounded-2xl overflow-hidden border border-[#2B1E1A]/10 mb-4"><div className="h-[118px] bg-[#C87A51] flex items-start p-3"><span className="text-[11px] bg-[#FBF9F5] px-2.5 py-[3px] rounded-full font-semibold" style={{color:"#993C1D"}}><Ic n="coffee" st={{marginRight:4}}/>Catalina's Café</span></div><div className="px-4 py-3.5"><p className="text-[11px] text-[#B4ADA6]">24 jul · Nuevo en barra</p><p className="text-[15px] font-semibold mt-1">Etiopía Guji · grano de especialidad</p><p className="text-xs text-[#7A8B7B] mt-1.5 leading-[1.55]">Lote de altura con notas a jazmín, durazno y un final cítrico. Disponible en barra y para llevar en grano de 250 g.</p></div></div>
        <div className="rounded-2xl overflow-hidden border border-[#2B1E1A]/10"><div className="h-[118px] bg-[#7A8B7B] flex items-start p-3"><span className="text-[11px] bg-[#FBF9F5] px-2.5 py-[3px] rounded-full font-semibold" style={{color:"#41503F"}}>El Obrador</span></div><div className="px-4 py-3.5"><p className="text-[11px] text-[#B4ADA6]">22 jul · Temporada</p><p className="text-[15px] font-semibold mt-1">Sándwich de autor: Pastrami curado en casa</p><p className="text-xs text-[#7A8B7B] mt-1.5 leading-[1.55]">Pastrami curado 8 días, pan de masa madre, pepinillos crocantes y mostaza a la miel. Por tiempo limitado.</p></div></div>
      </div></div><Nav/></div>,

    exp:()=> <div className="h-full flex flex-col"><div className="flex-1 overflow-y-auto"><Header title="Experiencias"/>
      <div className="px-5 pt-2">
        <div className="rounded-[18px] overflow-hidden border border-[#2B1E1A]/10 mb-3.5">
          <div className="h-[126px] bg-[#2B1E1A] flex flex-col justify-between p-3.5"><span className="self-start text-[11px] bg-[#C87A51] text-[#FBF9F5] px-2.5 py-[3px] rounded-full font-semibold">Acceso prioritario</span><div className="flex items-center gap-2 text-[#FBF9F5]"><Ic n="bread" st={{fontSize:26,color:"#C87A51"}}/><p className="text-lg font-semibold">Taller de Masa Madre</p></div></div>
          <div className="p-4">
            <div className="flex flex-col gap-2.5 mb-3.5">{[["calendar","Viernes 15 de agosto"],["clock","10:00 a 13:00 h"],["map-pin","El Obrador · Salón principal"],["users","Cupos limitados · quedan 5 de 12"]].map((r,i)=><div key={i} className="flex items-center gap-2.5 text-[13px]"><Ic n={r[0]} st={{color:"#C87A51",fontSize:17}}/>{r[1]}</div>)}</div>
            <p className="text-[12.5px] text-[#7A8B7B] leading-[1.6] mb-3.5">Aprendé a crear y mantener tu masa madre desde cero. Amasado, plegado y horneado de un pan de campo que te llevás a casa, guiado por nuestro panadero.</p>
            <p className="text-xs font-semibold mb-2">Incluye</p>
            <div className="flex flex-col gap-2 mb-4">{["Frasco con masa madre activa para llevar","Tu pan de campo recién horneado","Recetario impreso y café de especialidad"].map((t,i)=><div key={i} className="flex items-center gap-2 text-xs text-[#5F5A55]"><Ic n="check" st={{color:"#7A8B7B"}}/>{t}</div>)}</div>
            <div className="flex items-center justify-between border-t border-[#2B1E1A]/10 pt-3.5"><div><p className="text-[11px] text-[#B4ADA6]">Precio socio</p><p className="text-lg font-semibold">$18.000</p></div><button onClick={()=>go("ticket")} className="rounded-2xl px-[18px] py-3 text-[13px] font-semibold bg-[#C87A51] text-[#FBF9F5]">Reservar lugar</button></div>
          </div>
        </div>
        <div onClick={()=>alert("Cata de filtrados · pronto vas a poder reservar (demo)")} className="cursor-pointer bg-[#FBF9F5] border border-[#2B1E1A]/10 rounded-2xl p-4 flex items-center justify-between"><div className="flex items-center gap-3"><div className="w-[38px] h-[38px] rounded-xl flex items-center justify-center" style={{background:"rgba(200,122,81,0.14)",color:"#C87A51"}}><Ic n="cup"/></div><div><p className="text-[13px] font-semibold">Cata de filtrados</p><p className="text-[11px] text-[#7A8B7B]">Sáb 2 ago · 17:00 h</p></div></div><Ic n="chevron-right" st={{color:"#B4ADA6"}}/></div>
      </div></div><Nav/></div>,

    ticket:()=> <div className="h-full flex flex-col"><div className="flex-1 overflow-y-auto">
      <div className="bg-[#7A8B7B] text-[#FBF9F5] px-5 pt-6 pb-5 text-center relative"><span className="absolute left-[18px] top-[22px]" onClick={()=>go("exp")}><Ic n="arrow-left" st={{fontSize:22,cursor:"pointer"}}/></span><div className="w-16 h-16 mx-auto mb-3 rounded-full flex items-center justify-center" style={{background:"rgba(251,249,245,0.2)"}}><Ic n="check" st={{fontSize:30}}/></div><p className="text-[21px] font-semibold">Reserva confirmada</p><p className="text-xs opacity-90 mt-1.5">Te esperamos en el taller</p></div>
      <div className="p-5"><div className="bg-[#FBF9F5] border border-[#2B1E1A]/10 rounded-xl overflow-hidden"><div className="px-4.5 py-4 px-[18px]"><p className="text-base font-semibold">Taller de Masa Madre</p><div className="flex flex-col gap-2 mt-3">{[["calendar","Viernes 15 de agosto"],["clock","10:00 a 13:00 h"],["map-pin","El Obrador · Salón principal"]].map((r,i)=><div key={i} className="flex items-center gap-2.5 text-[12.5px]"><Ic n={r[0]} st={{color:"#C87A51",fontSize:16}}/>{r[1]}</div>)}</div></div><div className="border-t border-dashed border-[#2B1E1A]/20 p-[18px] text-center"><p className="text-xs text-[#7A8B7B] mb-3">Mostrá esta entrada al llegar</p><div className="w-[140px] h-[140px] mx-auto" dangerouslySetInnerHTML={{__html:makeQR("#7A8B7B")}}/><p className="mt-3 text-[13px] font-semibold tracking-[2px]">EXP-15A-042</p></div></div>
      <div className="mt-4"><Btn variant="ghost" onClick={()=>go("exp")}><Ic n="arrow-left"/> Volver a Experiencias</Btn></div></div>
    </div></div>,

    prize:()=> <div className="h-full flex flex-col"><div className="flex-1 overflow-y-auto">
      <div className="bg-[#C87A51] text-[#FBF9F5] px-5 pt-6 pb-5 text-center relative"><span className="absolute left-[18px] top-[22px]" onClick={()=>go("home")}><Ic n="arrow-left" st={{fontSize:22,cursor:"pointer"}}/></span><div className="w-[70px] h-[70px] mx-auto mb-3 rounded-full flex items-center justify-center" style={{background:"rgba(251,249,245,0.2)"}}><Ic n="gift" st={{fontSize:34}}/></div><p className="text-[22px] font-semibold">¡Premio conseguido!</p><p className="text-xs opacity-90 mt-1.5">Completaste tu tarjeta de Catalina's Café</p></div>
      <div className="p-5"><div className="border border-dashed rounded-2xl p-4 text-center" style={{borderColor:"rgba(200,122,81,0.5)"}}><p className="text-[11px] text-[#B4ADA6] tracking-[1px]">TU PREMIO</p><p className="text-[16px] font-semibold mt-1.5 leading-tight">Una infusión + un producto de bollería, a elección</p><p className="text-xs text-[#7A8B7B] mt-0.5">Gratis · válido 30 días</p></div>
      <div className="mt-4"><Btn variant="dark" onClick={()=>alert("Mostrá este código en caja para retirar tu premio (demo).")}><Ic n="qrcode"/> Canjear en caja</Btn></div><p className="mt-3 text-[11px] text-[#B4ADA6] text-center leading-[1.5]">Al canjear, empezás una tarjeta nueva automáticamente.</p></div>
    </div></div>,

    giftcard:()=> <div className="h-full flex flex-col"><div className="flex-1 overflow-y-auto p-5">
      <div className="flex items-center justify-between mb-2"><span onClick={()=>go("home")}><Ic n="arrow-left" st={{fontSize:22,cursor:"pointer"}}/></span><p className="text-lg font-semibold">Gift Card Dual</p><span className="w-5.5"></span></div>
      <div className="bg-[#2B1E1A] rounded-[20px] p-5 text-[#FBF9F5] relative overflow-hidden"><div className="absolute -right-8 -top-8 w-[110px] h-[110px] rounded-full" style={{background:"rgba(200,122,81,0.18)"}}></div><div className="absolute right-5 -bottom-10 w-[90px] h-[90px] rounded-full" style={{background:"rgba(122,139,123,0.2)"}}></div>
        <div className="relative"><div className="flex items-center gap-2 mb-4.5 mb-[18px]"><Ic n="gift" st={{color:"#C87A51",fontSize:20}}/><p className="text-[13px] font-semibold tracking-[0.5px]">GIFT CARD DUAL</p></div><p className="text-xs text-[#C8BEB6]">Un producto a elección en</p><div className="flex gap-2 my-2 mb-5"><span className="text-xs px-2.5 py-1 rounded-full" style={{background:"rgba(200,122,81,0.3)"}}>Catalina's Café</span><span className="text-xs px-2.5 py-1 rounded-full" style={{background:"rgba(122,139,123,0.35)"}}>El Obrador</span></div><div className="flex items-end justify-between"><div><p className="text-[10px] text-[#8F877F] tracking-[1px]">CÓDIGO</p><p className="text-base font-semibold tracking-[2px] mt-0.5">DUAL-7K29</p></div><div className="text-right"><p className="text-[10px] text-[#8F877F]">Vence</p><p className="text-[13px] mt-0.5">31 ago 2026</p></div></div></div>
      </div>
      <div className="flex gap-2.5 mt-4"><div className="flex-1 rounded-xl p-3 text-center" style={{background:"rgba(200,122,81,0.1)"}}><Ic n="checks" st={{color:"#C87A51",fontSize:18}}/><p className="text-[11px] mt-1.5" style={{color:"#99633B"}}>Válida en cualquiera de los dos locales</p></div><div className="flex-1 rounded-xl p-3 text-center" style={{background:"rgba(122,139,123,0.12)"}}><Ic n="clock" st={{color:"#7A8B7B",fontSize:18}}/><p className="text-[11px] mt-1.5" style={{color:"#41503F"}}>Un solo uso · antes del 31 de agosto</p></div></div>
      <div className="mt-4"><Btn onClick={()=>alert("Mostrá la Gift Card en caja para usarla (demo).")}><Ic n="qrcode"/> Usar en caja</Btn></div>
    </div></div>,

    profile:()=> <div className="h-full flex flex-col"><div className="flex-1 overflow-y-auto">
      <div className="px-5 pt-5 pb-1.5 flex items-center justify-between"><span onClick={()=>go("home")}><Ic n="arrow-left" st={{fontSize:22,cursor:"pointer"}}/></span><p className="text-lg font-semibold">Mi perfil</p><span className="w-5.5"></span></div>
      <div className="px-5 pt-2.5 text-center"><div className="w-[72px] h-[72px] rounded-full bg-[#2B1E1A] text-[#FBF9F5] flex items-center justify-center text-[26px] font-semibold mx-auto">F</div><p className="text-lg font-semibold mt-3">Fabián Martínez</p><p className="text-xs text-[#7A8B7B]">catalinassalta@gmail.com</p><p className="mt-2 inline-block text-[11px] px-3 py-1 rounded-full" style={{background:"rgba(200,122,81,0.12)",color:"#99633B"}}>Socio #01042 · desde jul 2026</p></div>
      <div className="px-5 pt-4.5 pt-[18px]"><div className="bg-[#FBF9F5] border border-[#2B1E1A]/10 rounded-xl overflow-hidden">
        {[["ticket","Mis reservas",()=>go("ticket")],["history","Historial de sellos",()=>openCard("cat")],["bell","Notificaciones",()=>go("notifs")],["help-circle","Ayuda",()=>go("help")]].map((r,i,a)=><div key={i} onClick={r[2]} className={"flex items-center justify-between px-4 py-[15px] cursor-pointer "+(i<a.length-1?"border-b border-[#2B1E1A]/[0.07]":"")}><span className="text-sm"><Ic n={r[0]} st={{color:"#7A8B7B",marginRight:10}}/>{r[1]}</span><Ic n="chevron-right" st={{color:"#B4ADA6"}}/></div>)}
      </div><div className="mt-4"><Btn variant="ghost" className="!text-[#A32D2D] !border-[#A32D2D]/25" onClick={()=>go("welcome")}><Ic n="logout"/> Cerrar sesión</Btn></div></div>
    </div></div>,

    notifs:()=> <div className="h-full flex flex-col"><div className="flex-1 overflow-y-auto">
      <div className="px-5 pt-5 pb-1.5 flex items-center justify-between"><span onClick={()=>go("profile")}><Ic n="arrow-left" st={{fontSize:22,cursor:"pointer"}}/></span><p className="text-lg font-semibold">Notificaciones</p><span className="w-5.5"></span></div>
      <div className="px-5 pt-1.5">{[["gift","#C87A51","rgba(200,122,81,0.14)","Estás cerca del Desafío Dual","Te falta 1 sello en Catalina's para ganar tu Gift Card.","hace 2 h"],["sparkles","#7A8B7B","rgba(122,139,123,0.16)","Nueva novedad en Catalina's","Ya está en barra el grano Etiopía Guji.","ayer"],["coffee","#C87A51","rgba(200,122,81,0.14)","¡Ganaste un premio!","Tenés una infusión gratis para retirar en Catalina's.","hace 3 días"],["cup","#7A8B7B","rgba(122,139,123,0.16)","Se abrió una experiencia","Reservá tu lugar en el Taller de Masa Madre.","hace 5 días"]].map((n,i,a)=><div key={i} className={"flex gap-3 py-3.5 "+(i<a.length-1?"border-b border-[#2B1E1A]/[0.07]":"")}><div className="w-[38px] h-[38px] rounded-xl flex-none flex items-center justify-center" style={{background:n[2],color:n[1]}}><Ic n={n[0]}/></div><div><p className="text-[13.5px] font-semibold">{n[3]}</p><p className="text-xs text-[#7A8B7B] mt-0.5 leading-[1.5]">{n[4]}</p><p className="text-[11px] text-[#B4ADA6] mt-1">{n[5]}</p></div></div>)}</div>
    </div></div>,

    help:()=> <div className="h-full flex flex-col"><div className="flex-1 overflow-y-auto">
      <div className="px-5 pt-5 pb-1.5 flex items-center justify-between"><span onClick={()=>go("profile")}><Ic n="arrow-left" st={{fontSize:22,cursor:"pointer"}}/></span><p className="text-lg font-semibold">Ayuda</p><span className="w-5.5"></span></div>
      <div className="px-5 pt-1.5"><p className="text-xs text-[#7A8B7B] font-semibold mb-2.5">Preguntas frecuentes</p><div className="bg-[#FBF9F5] border border-[#2B1E1A]/10 rounded-xl overflow-hidden">
        {[["¿Cómo sumo sellos?","Mostrá tu código QR en la caja y el local te suma el sello al instante."],["¿Qué es el Desafío Dual?","Si completás las dos tarjetas en el mismo mes, ganás una Gift Card para usar en cualquiera de los dos locales."],["¿Los sellos vencen?","Los sellos de cada tarjeta no vencen. El Desafío Dual, en cambio, se reinicia cada mes."]].map((q,i,a)=><div key={i} className={"px-4 py-3.5 "+(i<a.length-1?"border-b border-[#2B1E1A]/[0.07]":"")}><p className="text-[13.5px] font-semibold">{q[0]}</p><p className="text-xs text-[#7A8B7B] mt-1 leading-[1.5]">{q[1]}</p></div>)}
      </div>
      <p className="text-xs text-[#7A8B7B] font-semibold mt-4.5 mt-[18px] mb-2.5">¿Necesitás ayuda?</p><div className="bg-[#FBF9F5] border border-[#2B1E1A]/10 rounded-xl overflow-hidden">
        <div onClick={()=>alert("Abriendo WhatsApp (demo)")} className="flex items-center justify-between px-4 py-3.5 border-b border-[#2B1E1A]/[0.07] cursor-pointer"><span className="text-sm"><Ic n="brand-whatsapp" st={{color:"#7A8B7B",marginRight:10}}/>Escribinos por WhatsApp</span><Ic n="chevron-right" st={{color:"#B4ADA6"}}/></div>
        <div onClick={()=>alert("Abriendo correo (demo)")} className="flex items-center justify-between px-4 py-3.5 cursor-pointer"><span className="text-sm"><Ic n="mail" st={{color:"#7A8B7B",marginRight:10}}/>Enviar un correo</span><Ic n="chevron-right" st={{color:"#B4ADA6"}}/></div>
      </div></div>
    </div></div>,

    cajaLogin:()=> <div className="h-full flex flex-col bg-[#2B1E1A] text-[#FBF9F5]">
      <div className="px-5 py-4 flex items-center justify-between"><div className="flex items-center gap-2.5"><Ic n="cash-register" st={{fontSize:20,color:"#C87A51"}}/><div><p className="text-sm font-semibold">Modo Mozo · Catalina's Café</p><p className="text-[11px] text-[#C8BEB6]"><Ic n="lock" st={{fontSize:11}}/> Dispositivo del local</p></div></div><Ic n="x" cls="cursor-pointer" st={{color:"#C8BEB6"}}/></div>
      <div className="flex-1 p-5 text-center"><div className="w-[54px] h-[54px] rounded-xl mx-auto flex items-center justify-center mt-3" style={{background:"rgba(200,122,81,0.16)",color:"#C87A51"}}><Ic n="user-shield" st={{fontSize:26}}/></div><p className="text-[17px] font-semibold mt-3.5">Ingresá tu PIN de mozo</p><p className="text-xs text-[#C8BEB6] max-w-[235px] mx-auto mt-1.5 leading-[1.5]">Identifica quién opera el turno, para registrar cada sello y cada canje.</p>
        <p className="font-mono text-[30px] tracking-[12px] my-4 min-h-[38px]">{"____".split("").map((u,i)=>i<cpin.length?"*":"_").join("")}</p>
        <div className="grid grid-cols-3 gap-2.5 max-w-[250px] mx-auto">{["1","2","3","4","5","6","7","8","9"].map(k=><button key={k} onClick={()=>pressCpin(k)} className="rounded-2xl py-4 text-lg bg-[#FBF9F5]/[0.08] border border-[#FBF9F5]/15">{k}</button>)}<button onClick={()=>setCpin(c=>c.slice(0,-1))} className="rounded-2xl py-4 text-lg border border-[#FBF9F5]/15 text-[#C8BEB6]"><Ic n="backspace"/></button><button onClick={()=>pressCpin("0")} className="rounded-2xl py-4 text-lg bg-[#FBF9F5]/[0.08] border border-[#FBF9F5]/15">0</button><button onClick={()=>{ if(cpin.length>=1){setCpin("");go("cajaScan");} }} className="rounded-2xl py-4 text-lg bg-[#C87A51]"><Ic n="check"/></button></div>
      </div></div>,

    cajaScan:()=> <div className="h-full flex flex-col">
      <div className="bg-[#2B1E1A] text-[#FBF9F5] px-5 py-4 flex items-center justify-between"><div className="flex items-center gap-2.5"><Ic n="device-tablet" st={{fontSize:20,color:"#C87A51"}}/><div><p className="text-sm font-semibold">Modo Mozo · Catalina's Café</p><p className="text-[11px] text-[#C8BEB6]"><Ic n="lock" st={{fontSize:11}}/> Dispositivo fijo del local</p></div></div><span className="text-[11px] px-2.5 py-[3px] rounded-full" style={{background:"rgba(122,139,123,0.35)",color:"#FBF9F5"}}>En línea</span></div>
      <div className="flex-1 overflow-y-auto p-5 text-center bg-[#FBF9F5]"><p className="text-lg font-semibold mt-3">Escaneá el código del cliente</p><p className="text-xs text-[#7A8B7B]">Apuntá al QR que muestra en su teléfono</p>
        <div className="relative w-[186px] h-[186px] mx-auto mt-4 bg-[#2B1E1A] rounded-[22px] flex items-center justify-center">{[["top-4 left-4","border-t-[3px] border-l-[3px] rounded-tl-lg"],["top-4 right-4","border-t-[3px] border-r-[3px] rounded-tr-lg"],["bottom-4 left-4","border-b-[3px] border-l-[3px] rounded-bl-lg"],["bottom-4 right-4","border-b-[3px] border-r-[3px] rounded-br-lg"]].map((c,i)=><div key={i} className={"absolute w-8 h-8 border-[#C87A51] "+c[0]+" "+c[1]}></div>)}<Ic n="qrcode" st={{fontSize:60,color:"rgba(251,249,245,0.22)"}}/></div>
        <p className="text-[13px] font-semibold mt-4">¿Cuántos sellos otorgar?</p>
        <div className="flex gap-2.5 mt-2.5 max-w-[280px] mx-auto">{[1,2].map(n=><button key={n} onClick={()=>setStampN(n)} className={"flex-1 rounded-2xl py-3 text-sm font-semibold border transition-colors "+(stampN===n?"bg-[#2B1E1A] text-[#FBF9F5] border-[#2B1E1A]":"bg-[#FBF9F5] text-[#2B1E1A] border-[#2B1E1A]/20")}>{n} {n===1?"sello":"sellos"}</button>)}</div>
        <p className="text-[11px] text-[#B4ADA6] mt-2">Máximo 2 por visita</p>
        <div className="mt-4"><Btn variant="dark" onClick={()=>{ db.sumarSellos("cliente-demo",local,stampN); setScreen("cajaStamp"); }}><Ic n="scan"/> Confirmar lectura · +{stampN} {stampN===1?"sello":"sellos"}</Btn></div>
        <div className="mt-3"><Btn variant="ghost" onClick={()=>{setPin("");go("cajaPin");}}><Ic n="keyboard"/> La cámara no lee · ingresar código</Btn></div>
        <div className="mt-2.5"><Btn variant="ghost" onClick={()=>go("cajaRedeem")}><Ic n="gift"/> Canje de premio</Btn></div>
        <p className="mt-4 text-[11px] text-[#8F877F]">¿Volver a la app del cliente? <span onClick={()=>go("welcome")} className="text-[#C87A51] font-semibold cursor-pointer">Salir del modo mozo</span></p>
      </div></div>,
    cajaStamp:()=> <div className="h-full flex flex-col">
      <div className="bg-[#2B1E1A] text-[#FBF9F5] px-5 py-4 flex items-center justify-between"><div className="flex items-center gap-2.5"><Ic n="cash-register" st={{fontSize:20,color:"#C87A51"}}/><div><p className="text-sm font-semibold">Mozo · El Obrador</p><p className="text-[11px] text-[#C8BEB6]">Terminal 1 · Sofía</p></div></div><span className="text-[11px] px-2.5 py-[3px] rounded-full" style={{background:"rgba(122,139,123,0.35)",color:"#FBF9F5"}}>En línea</span></div>
      <div className="flex-1 overflow-y-auto p-5 text-center bg-[#FBF9F5]"><div className="w-[78px] h-[78px] mx-auto mt-5.5 mt-6 rounded-full flex items-center justify-center" style={{background:"rgba(122,139,123,0.18)"}}><div className="w-14 h-14 rounded-full bg-[#7A8B7B] flex items-center justify-center"><Ic n="check" st={{fontSize:32,color:"#FBF9F5"}}/></div></div>
        <p className="text-xl font-semibold mt-4">{stampN===2?"2 sellos sumados":"Sello sumado"}</p><p className="text-xs text-[#7A8B7B]">El Obrador · Sandwichería de autor</p>
        <div className="bg-[#FBF9F5] border border-[#2B1E1A]/10 rounded-xl p-4 mt-4.5 mt-[18px] text-left"><div className="flex items-center justify-between pb-3.5 border-b border-[#2B1E1A]/[0.08]"><div className="flex items-center gap-3"><div className="w-10 h-10 rounded-full bg-[#C87A51] text-[#FBF9F5] flex items-center justify-center text-sm font-semibold">F</div><div><p className="text-sm font-semibold">Fabián M.</p><p className="text-[11px] text-[#B4ADA6]">Socio #01042 · validado por QR</p></div></div></div><div className="flex items-center justify-between pt-3.5"><div><p className="text-xs text-[#7A8B7B]">Sellos de El Obrador</p><p className="text-[22px] font-semibold">{4+stampN} <span className="text-sm text-[#B4ADA6]">/ 9</span></p></div><div className="flex gap-1.5">{Array.from({length:5}).map((_,i)=><span key={i} className="w-[9px] h-[9px] rounded-full" style={{background:i<3+stampN?"#7A8B7B":"rgba(122,139,123,0.25)"}}></span>)}</div></div></div>
        <div className="flex items-center gap-2.5 mt-3 px-3.5 py-2.5 rounded-xl text-left" style={{background:"rgba(200,122,81,0.1)",border:"1px solid rgba(200,122,81,0.22)"}}><Ic n="gift" st={{color:"#C87A51",fontSize:18}}/><p className="text-xs leading-[1.45]" style={{color:"#99633B"}}>Desafío Dual: le faltan {5-(stampN-1)} en El Obrador y 1 en Catalina's este mes.</p></div>
        <div className="flex gap-2.5 mt-4.5 mt-[18px]"><button onClick={()=>go("cajaScan")} className="flex-none w-[52px] rounded-xl py-3.5 bg-[#FBF9F5] border border-[#2B1E1A]/15"><Ic n="arrow-back-up"/></button><button onClick={()=>go("cajaScan")} className="flex-1 rounded-xl py-3.5 bg-[#2B1E1A] text-[#FBF9F5] text-sm font-semibold flex items-center justify-center gap-2"><Ic n="scan"/>Escanear siguiente</button></div>
      </div></div>,

    cajaRedeem:()=> <div className="h-full flex flex-col">
      <div className="bg-[#2B1E1A] text-[#FBF9F5] px-5 py-4 flex items-center justify-between"><div className="flex items-center gap-2.5"><Ic n="cash-register" st={{fontSize:20,color:"#C87A51"}}/><div><p className="text-sm font-semibold">Mozo · Catalina's Café</p><p className="text-[11px] text-[#C8BEB6]">Terminal 1 · Sofía</p></div></div><span className="text-[11px] px-2.5 py-[3px] rounded-full" style={{background:"rgba(122,139,123,0.35)",color:"#FBF9F5"}}>En línea</span></div>
      <div className="flex-1 overflow-y-auto p-5 text-center bg-[#FBF9F5]"><div className="inline-flex items-center gap-2 px-3.5 py-1.5 rounded-full text-xs font-semibold mt-3.5" style={{background:"rgba(200,122,81,0.14)",color:"#99633B"}}><Ic n="gift" st={{fontSize:15}}/>Canje de premio</div>
        <p className="text-xl font-semibold mt-4">Entregar a Fabián M.</p><p className="text-xs text-[#B4ADA6]">Socio #01042 · validado por QR</p>
        <div className="rounded-2xl p-4 mt-4.5 mt-[18px]" style={{border:"1px solid rgba(200,122,81,0.3)"}}><p className="text-[11px] text-[#B4ADA6] tracking-[1px]">EL CLIENTE RETIRA</p><p className="text-[17px] font-semibold mt-2 leading-tight">Una infusión + un producto de bollería</p><p className="text-xs text-[#7A8B7B]">Premio 9+1</p></div>
        <div className="flex items-center gap-2.5 mt-3.5 px-3.5 py-2.5 rounded-xl text-left" style={{background:"rgba(122,139,123,0.1)"}}><Ic n="info-circle" st={{color:"#7A8B7B",fontSize:17}}/><p className="text-[11.5px] leading-[1.45]" style={{color:"#41503F"}}>Al confirmar, el premio se marca como usado y no se puede volver a canjear.</p></div>
        <div className="flex gap-2.5 mt-4.5 mt-[18px]"><button onClick={()=>go("cajaScan")} className="flex-1 rounded-xl py-3.5 bg-[#FBF9F5] border border-[#2B1E1A]/15 text-sm font-semibold">Cancelar</button><button onClick={()=>{ db.canjearPremio("cliente-demo",local); alert("Premio entregado (demo)."); go("cajaScan"); }} className="flex-[1.4] rounded-xl py-3.5 bg-[#7A8B7B] text-[#FBF9F5] text-sm font-semibold flex items-center justify-center gap-2"><Ic n="check"/>Confirmar entrega</button></div>
      </div></div>,

    cajaPin:()=> <div className="h-full flex flex-col bg-[#2B1E1A] text-[#FBF9F5]">
      <div className="px-5 py-4 flex items-center justify-between"><div className="flex items-center gap-2.5"><Ic n="cash-register" st={{fontSize:20,color:"#C87A51"}}/><div><p className="text-sm font-semibold">Mozo · Catalina's Café</p><p className="text-[11px] text-[#C8BEB6]">Ingreso manual por PIN</p></div></div><Ic n="x" cls="cursor-pointer" st={{color:"#C8BEB6"}}/></div>
      <div className="flex-1 p-5 text-center"><p className="text-base font-semibold mt-2">Ingresá el PIN del cliente</p><p className="text-xs text-[#C8BEB6]">Los 4 dígitos que ve en su pantalla</p>
        <p className="font-mono text-[30px] tracking-[12px] my-4 min-h-[38px]">{"____".split("").map((u,i)=>i<pin.length?"*":"_").join("")}</p>
        <div className="grid grid-cols-3 gap-2.5 max-w-[250px] mx-auto">{["1","2","3","4","5","6","7","8","9"].map(k=><button key={k} onClick={()=>pressPin(k)} className="rounded-2xl py-4 text-lg bg-[#FBF9F5]/[0.08] border border-[#FBF9F5]/15">{k}</button>)}<button onClick={()=>setPin(p=>p.slice(0,-1))} className="rounded-2xl py-4 text-lg border border-[#FBF9F5]/15 text-[#C8BEB6]"><Ic n="backspace"/></button><button onClick={()=>pressPin("0")} className="rounded-2xl py-4 text-lg bg-[#FBF9F5]/[0.08] border border-[#FBF9F5]/15">0</button><button onClick={()=>{ if(pin.length>=1){setPin("");setStampN(1);go("cajaStamp");} }} className="rounded-2xl py-4 text-lg bg-[#C87A51]"><Ic n="check"/></button></div>
        <p className="mt-4"><span onClick={()=>go("cajaError")} className="text-[11px] text-[#8F877F] cursor-pointer">Ver qué pasa si el código venció</span></p>
      </div></div>,

    cajaError:()=> <div className="h-full flex flex-col bg-[#2B1E1A] text-[#FBF9F5]">
      <div className="px-5 py-4 flex items-center justify-between"><div className="flex items-center gap-2.5"><Ic n="cash-register" st={{fontSize:20,color:"#C87A51"}}/><div><p className="text-sm font-semibold">Mozo · Catalina's Café</p><p className="text-[11px] text-[#C8BEB6]">Terminal 1 · Sofía</p></div></div></div>
      <div className="flex-1 p-5 text-center"><div className="w-[74px] h-[74px] rounded-full mx-auto mt-11 flex items-center justify-center" style={{background:"rgba(163,45,45,0.18)"}}><Ic n="alert-triangle" st={{fontSize:34,color:"#E8908C"}}/></div><p className="text-xl font-semibold mt-4">Código vencido</p><p className="text-[12.5px] text-[#C8BEB6] leading-[1.6] mt-2 max-w-[250px] mx-auto">El código del cliente expiró. Pedile que actualice su pantalla y escaneá de nuevo.</p><div className="max-w-[250px] mx-auto mt-6"><Btn variant="dark" onClick={()=>go("cajaScan")}><Ic n="scan"/> Volver a escanear</Btn></div></div>
    </div>
  };

  return <div className="min-h-screen w-full bg-[#E4DED6] flex flex-col items-center justify-center gap-4 p-5" style={{fontFamily:"-apple-system,Segoe UI,Roboto,sans-serif"}}>
    <p className="text-xs text-[#7A6E64] text-center max-w-[360px]">Prototipo · App de fidelización Catalina's Café + El Obrador. Tocá los botones y la barra inferior.</p>
    <div className="w-[360px] h-[720px] rounded-[34px] overflow-hidden relative flex flex-col bg-[#FBF9F5] text-[#2B1E1A]" style={{boxShadow:"0 24px 70px rgba(43,30,26,0.4)"}}>
      {(SCREENS[screen]||SCREENS.welcome)()}
    </div>
  </div>;
}

export default App;
